"""Figure for the trigger study -> reports/figures/bl_trg_logic.png"""
import sys, os, warnings; sys.path.insert(0, '.'); warnings.filterwarnings('ignore')
import numpy as np, pandas as pd, json, matplotlib; matplotlib.use('Agg'); import matplotlib.pyplot as plt
from bl_common import OUT
FIG = os.path.join(os.path.dirname(OUT), 'reports', 'figures'); os.makedirs(FIG, exist_ok=True)
S = pd.read_csv(f'{OUT}/bl_trg_bandscan.csv'); B = pd.read_csv(f'{OUT}/bl_trg_blocks.csv'); TR = pd.read_csv(f'{OUT}/bl_trg_tree.csv'); R3 = json.load(open(f'{OUT}/bl_summary_trg3.json')); R1 = json.load(open(f'{OUT}/bl_summary_trg1.json')); RF = pd.read_csv(f'{OUT}/bl_trg_refract.csv')
fig, ax = plt.subplots(2, 2, figsize=(13.5, 9.5))
a = ax[0, 0]; r = S[S.window != 'EXP']; n = r.window.str[1:].astype(int); a.plot(n, r.AUC, 'o-', color='#d62728', label='both edges'); a.plot(n, r.AUC_upper_edge, 's--', color='#1f77b4', ms=3, label='upper-edge events only'); a.plot(n, r.AUC_lower_edge, '^--', color='#2ca02c', ms=3, label='lower-edge events only'); a.axhline(S.AUC[S.window == 'EXP'].iloc[0], color='k', ls=':', label='expanding range since the open'); a.axvspan(40, 70, color='k', alpha=.07); a.set_xlabel('rolling channel length N (minutes)'); a.set_ylabel('activation AUC'); a.legend(fontsize=7, loc='lower center'); a.set_title('A. Window: 40–70 min indistinguishable; "since the open" rejected')
a = ax[0, 1]; fa = pd.DataFrame(R3['fine_age']).T; fa.columns = ['minutes', 'pairs', 'per1000']; a.bar(range(len(fa)), fa.per1000, color='#d62728'); a.set_xticks(range(len(fa))); a.set_xticklabels([k.replace('(', '').replace(']', '').replace(', ', '–').replace('.0', '') for k in fa.index], fontsize=7); inside = RF[(RF.population == 'inside range (no LA breakout): minutes since last reactive pair')]; a.axhline(inside.pair_minutes.sum() / inside.minutes.sum() * 1000, color='k', ls=':', label='inside the range (no breakout)'); a.set_xlabel('minutes since the previous reactive pair'); a.set_ylabel('pairs per 1000 breakout minutes'); a.legend(fontsize=8); a.set_title('B. At a breakout, a pair is likelier the longer since the last one')
for i, (p, m) in enumerate(zip(fa.pairs, fa.minutes)): a.text(i, fa.per1000.iloc[i] + 6, f'{int(p)}/{int(m)}', ha='center', fontsize=6)
a = ax[1, 0]; x = np.arange(len(TR)); a.bar(x - .2, TR.precision, .4, color='#1f77b4', label='precision'); a.bar(x + .2, TR.recall, .4, color='#ff7f0e', label='recall'); a.axhline(.5, color='k', ls='--', lw=1); a.set_xticks(x); a.set_xticklabels(['tree\n(all causal)', 'tree\n(edge only)', 'completed-bar\nbreakout', 'LOOK-AHEAD\nbreakout'], fontsize=8); a.set_ylim(0, 1); a.legend(fontsize=8); a.set_title('C. No rule reaches precision and recall of 0.5 (dashed)')
for i, (p, r_) in enumerate(zip(TR.precision, TR.recall)): a.text(i - .2, p + .02, f'{p:.2f}', ha='center', fontsize=7); a.text(i + .2, r_ + .02, f'{r_:.2f}', ha='center', fontsize=7)
a = ax[1, 1]; d = B[B.population.str.startswith('LOOK-AHEAD') & (B.features != 'edge only') & (B.features != 'all blocks')]; lab = [f.replace('edge + ', '') for f in d[d.model == 'gb'].features]; xx = np.arange(len(lab))
for k, (m, c, off) in enumerate((('lr', '#1f77b4', -.18), ('gb', '#2ca02c', .18))):
    q = d[d.model == m]; a.errorbar(xx + off, q.gain_vs_edge_only, yerr=[q.gain_vs_edge_only - q.gain_lo, q.gain_hi - q.gain_vs_edge_only], fmt='o', color=c, capsize=3, label={'lr': 'logistic', 'gb': 'gradient boosting'}[m])
a.axhline(0, color='k', lw=.8); a.axhline(.03, color='r', ls=':', lw=1); a.set_xticks(xx); a.set_xticklabels(lab); a.set_ylabel('AUC gain over the edge-only model'); a.legend(fontsize=8); a.set_title('D. Among breakout minutes only order-activity timing adds anything')
plt.tight_layout(); plt.savefig(f'{FIG}/bl_trg_logic.png', dpi=130); print('ok')
